const std = @import("std");
const js = @import("js");
fn script(raw: *anyopaque, _: js.Value, args: []const js.Value) js.HostError!js.Value {
    const machine: *js.Interpreter = @ptrCast(@alignCast(raw));
    const ctx: *js.Context = @ptrCast(@alignCast(machine.gc_realm_context.?));
    return ctx.evaluate(args[0].asStr()) catch |err| switch (err) {
        error.Throw => { machine.exception = ctx.exception.?; return error.Throw; },
        else => return error.OutOfMemory,
    };
}
pub fn main() !void {
    for ([_]bool{false, true}) |bytecode| {
        const ctx = try js.Context.createWithTestingOptions(std.heap.page_allocator, .{ .step_budget = 2000, .bytecode_execution_mode = if(bytecode) .required else .tree_walker });
        defer ctx.destroy();
        var machine = ctx.interpreter();
        const f = try machine.newObject();
        f.asObj().native = script;
        try ctx.global_object.setOwn(ctx.arena(), ctx.root_shape, "hostScript", f);
        const source = "var calls=0;for(var round=0;round<20;round++){hostScript('for(var inner=0;inner<100;inner++){}');calls++;}calls";
        if(ctx.evaluate(source)) |result| {
            std.debug.print("BUDGET RESET REPRODUCED: mode={s}, budget=2000, completed={d} nested scripts\n", .{if(bytecode) "required-bytecode" else "tree-walker", result.asNum()});
        } else |err| {
            std.debug.print("NESTED EVALUATION EXHAUSTED: mode={s}, error={s}\n", .{if(bytecode) "required-bytecode" else "tree-walker", @errorName(err)});
        }
        const subsequent = try ctx.evaluate("7");
        if(subsequent.asNum()!=7) return error.FreshEntryFailed;
    }
}

