#include <JavaScriptCore/JavaScript.h>
#include <stdio.h>
static JSValueRef script(JSContextRef c, JSObjectRef f, JSObjectRef t, size_t n, const JSValueRef a[], JSValueRef *ex) {
    (void)f; (void)t;
    if(n!=1) return JSValueMakeUndefined(c);
    JSStringRef s=JSValueToStringCopy(c,a[0],ex);
    if(!s) return NULL;
    JSValueRef r=JSEvaluateScript(c,s,NULL,NULL,1,ex);
    JSStringRelease(s);return r;
}
static int evaluate(JSContextRef c,const char *text) {
    JSStringRef s=JSStringCreateWithUTF8CString(text);JSValueRef ex=NULL;
    JSValueRef r=JSEvaluateScript(c,s,NULL,NULL,1,&ex);JSStringRelease(s);
    if(!r || ex) { fputs("Script failed\n",stderr);return 1; }
    JSStringRef v=JSValueToStringCopy(c,r,&ex);char out[512];
    if(!v || ex)return 1;JSStringGetUTF8CString(v,out,sizeof(out));JSStringRelease(v);puts(out);return 0;
}
int main(void) {
    JSGlobalContextRef c=JSGlobalContextCreate(NULL);
    JSStringRef name=JSStringCreateWithUTF8CString("hostScript");JSValueRef ex=NULL;
    JSObjectRef f=JSObjectMakeFunctionWithCallback(c,name,script);
    JSObjectSetProperty(c,JSContextGetGlobalObject(c),name,f,kJSPropertyAttributeNone,&ex);JSStringRelease(name);
    if(ex)return 1;
    int status=evaluate(c,"var trace=[];Promise.resolve().then(()=>trace.push('job'));trace.push('before');hostScript(\"trace.push('nested')\");trace.push('after');trace.join(',')");
    status|=evaluate(c,"trace.join(',')");JSGlobalContextRelease(c);return status;
}

