import vm from 'node:vm';
globalThis.vmOrderTrace=[];
Promise.resolve().then(()=>vmOrderTrace.push('job'));
vmOrderTrace.push('before');
vm.runInThisContext("vmOrderTrace.push('nested')");
vmOrderTrace.push('after');
if(vmOrderTrace.join(',')!=='before,nested,after')throw new Error('premature nested Script checkpoint: '+vmOrderTrace);
console.log(vmOrderTrace.join(','));
await Promise.resolve();
if(vmOrderTrace.join(',')!=='before,nested,after,job')throw new Error('missing outer checkpoint: '+vmOrderTrace);
console.log(vmOrderTrace.join(','));
